"""evt -- fingerprint for discrete state sequences via transition timing, DETECTOR ONLY.

Detect (blind): for every transition observed at tick resolution, a keyed bit says which parity its tick should have.
T = (2 * #matches - N) / sqrt(N); under H0 the matches are Binomial(N, 1/2) exactly.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..addressing import AddressSpec, compute_address
from ..prf import domain_id, prf_sign
from ._stats import z_to_p


NAME = "evt"


BUCKET = 64


def _codes(s: pd.Series) -> np.ndarray:
    """Content-based stable integer code per state value (independent of order of appearance)."""
    import hashlib
    u = pd.unique(s.astype(str))
    m = {v: int.from_bytes(hashlib.blake2b(v.encode(), digest_size=4).digest(), "little") for v in u}
    return s.astype(str).map(m).to_numpy(np.int64)


def _bits(key, col, frm, to, tick):
    idx = (frm * 1_000_003 + to) * 1_000_033 + (tick // BUCKET)
    return prf_sign(key, domain_id("evt:" + col), idx.astype(np.int64)) > 0


def detect(df: pd.DataFrame, key: bytes, addr: AddressSpec, columns: list[str], max_shift: int = 0, **_):
    """Pooled binomial test over transitions observed at tick resolution. With max_shift S > 0 (time or position
    addressing) the copy may have been re-stamped by a constant offset: z is computed for every offset in [-S, S]
    (the copy being `off` ticks ahead of the release), ONE offset shared by all columns is chosen, and the p-value is
    Bonferroni-corrected over the 2S+1 offsets tried. Each offset's statistic is an exact binomial under H0 (the
    keyed bits do not depend on the data), so the corrected p stays valid. Without it, an odd shift flips every
    parity and the plain z becomes strongly negative (packaging/SPLIT_PLAN.md R12). The keyed bits depend only on the
    parity of the tick and its bucket of BUCKET ticks, so offsets of the same parity give (almost) the same z: the
    reported `shift` is ONE of the equivalent offsets, not an estimate of the actual re-stamping."""
    S = int(max_shift) if addr.kind != "keys" else 0
    offs = np.arange(-S, S + 1)
    per, zz, ns = {}, {}, {}
    ad = compute_address(df, addr)
    order = np.argsort(ad, kind="stable")
    for c in columns:
        if c not in df.columns:
            per[c] = {"missing": True}
            continue
        code = _codes(df[c])[order]
        tick = ad[order]
        tr = np.flatnonzero(code[1:] != code[:-1]) + 1
        tr = tr[np.abs(tick[tr] - tick[tr - 1]) == 1]          # only transitions observed at tick resolution
        if tr.size < 10:
            per[c] = {"skipped": True, "transitions": int(tr.size)}
            continue
        N = int(tr.size)
        z_off, rate = [], []
        for off in offs:
            t0 = tick[tr] - off                                  # tick in the release's clock
            match = ((t0 & 1) == 1) == _bits(key, c, code[tr - 1], code[tr], t0)
            z_off.append(float((2 * match.sum() - N) / np.sqrt(N)))
            rate.append(float(match.mean()))
        zz[c], ns[c] = np.array(z_off), N
        per[c] = {"n": N, "match_rate_by_offset": rate}
    if not zz:
        return {"method": NAME, "columns": per, "z": 0.0, "p": 1.0}
    w = np.sqrt(np.array([ns[c] for c in zz], float))
    Z = (w[:, None] * np.vstack([zz[c] for c in zz])).sum(0) / np.sqrt(np.sum(w ** 2))   # pooled binomial
    j = int(np.argmax(Z)) if S else 0
    for c in zz:
        rates = per[c].pop("match_rate_by_offset")
        per[c].update({"z": float(zz[c][j]), "match_rate": rates[j], "p": z_to_p(float(zz[c][j])),
                       "tests": len(offs), "shift": int(offs[j])})
    z = float(Z[j])
    out = {"method": NAME, "columns": per, "z": z, "p": float(min(1.0, z_to_p(z) * len(offs)))}
    if S:
        out.update({"shift": int(offs[j]), "offsets_tested": len(offs), "z_by_offset": [float(v) for v in Z],
                    "shift_note": "evt identifies only the parity of a re-stamping; shift is one equivalent offset"})
    return out
